nasal.load:


var self = cmdarg();
print("Model load F-15 ", self.getPath(), " ID ",_module_id);
var modelPath = self.getNode("sim/model/path").getValue();
if (modelPath != nil and find("F-15D.xml", modelPath) != -1) {
   self.getNode("sim/model/f15/variant",1).setValue("D");
    print ("D variant");
} elsif (modelPath != nil and find("F-15EX.xml", modelPath) != -1) {
   self.getNode("sim/model/f15/variant",1).setValue("EX");
    print ("EX variant");
} else {
   self.getNode("sim/model/f15/variant",1).setValue("C");
    print ("C variant");
}

var livery_update = aircraft.livery_update.new("Aircraft/F-15/Models/Liveries", 10 );

# nasal module locator
var modelPathElements = split("/", modelPath);
var basePath = "";
if (size(modelPathElements) > 3)
  basePath = string.join("/",modelPathElements[0:size(modelPathElements)-3]);

var locate_nasal = func(nasal_file){
    var fn_nasal_file = resolvepath("Nasal") ~ "/" ~ nasal_file;
    if (io.stat(fn_nasal_file) == nil)
      fn_nasal_file = getprop("/sim/fg-root") ~ "/Nasal/" ~ nasal_file;

    if (io.stat(fn_nasal_file) == nil)
      fn_nasal_file = getprop("/sim/fg-root") ~ basePath ~ "/Nasal/" ~ nasal_file;

    if (io.stat(fn_nasal_file) == nil)
      fn_nasal_file = resolvepath(basePath ~ "/Nasal") ~ "/" ~ nasal_file;

    if (io.stat(fn_nasal_file) == nil)
      fn_nasal_file = getprop("/sim/fg-root") ~ "/" ~ basePath ~ "Nasal/" ~ nasal_file;

    if (io.stat(fn_nasal_file) == nil) {
        print("Error could not locate ", fn_nasal_file);
        return nil;
    }

    print("Loading ",nasal_file," from ",fn_nasal_file);
    return fn_nasal_file;
}
;
# end nasal file locator

# Load the needed modules if it hasn't been done yet.
# - we assume that if we have the network we have the VSD. This should always be the case.
if (!contains(globals, "f15_net")) {
    print("LOAD F-15 mp network", self.getPath());
    var fn_net = locate_nasal("mp-network.nas");

    if (fn_net != nil) {
        io.load_nasal(fn_net, "f15_net");

        # Initialize network as observer.
        f15_net.mp_network_init(0);
    }
}
#print("Model load VSD");
if (contains(globals, "f15vsd")) {
    print("F-15: Model init VSD _module_id=",_module_id);
    # ensure that everyone knows that we have just been loaded.
    var modelNotification = emesary.Notification.new("F15Model", _module_id);
    modelNotification.root_node = self;
    emesary.GlobalTransmitter.PrintRecipients();
    emesary.GlobalTransmitter.NotifyAll(modelNotification);

} else {
    print("F-15: not backseat so not loading backseat VSD");
}


# set reasonable values for sound volumes
setprop("fdm/jsbsim/systems/sound/engine-efflux-l-volume",0.3);
setprop("fdm/jsbsim/systems/sound/engine-efflux-r-volume",0.3);
setprop("fdm/jsbsim/systems/sound/engine-jet-augmentation-l-volume",0);
setprop("fdm/jsbsim/systems/sound/engine-jet-augmentation-r-volume",0);
setprop("fdm/jsbsim/systems/sound/engine-jet-exhaust-l-volume",0.3);
setprop("fdm/jsbsim/systems/sound/engine-jet-exhaust-r-volume",0.3);
setprop("fdm/jsbsim/systems/sound/engine-jet-intake-l-volume",0.8);
setprop("fdm/jsbsim/systems/sound/engine-jet-intake-r-volume",0.8);
setprop("fdm/jsbsim/systems/sound/engine-n2-l-volume",0.4);
setprop("fdm/jsbsim/systems/sound/engine-n2-r-volume",0.4);

nasal.unload:

print("UNLOAD F-15 ", getprop("sim/model/path"), " ID ",_module_id);
#cmdarg().getNode("sim/model/ac-type", 1).setValue(""); # Dual-control
livery_update.stop();
emesary.GlobalTransmitter.NotifyAll(emesary.Notification.new("F15ModelUnload", _module_id));
